import{_ as t,o,c as d,ag as s}from"./chunks/framework.D1z9wg1y.js";const p=JSON.parse('{"title":"The harness command","description":"","frontmatter":{},"headers":[],"relativePath":"harness-command.md","filePath":"harness-command.md"}'),a={name:"harness-command.md"};function r(l,e,n,c,i,h){return o(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="the-harness-command" tabindex="-1">The <code>harness</code> command <a class="header-anchor" href="#the-harness-command" aria-label="Permalink to &quot;The `harness` command&quot;">​</a></h1><p><code>bin/harness</code> is the front door to the tooling. It needs Python 3.11 or later and nothing beyond the standard library. Put <code>bin/</code> on the <code>PATH</code>, as <a href="https://github.com/michakraus/ResearchHarness#installation" target="_blank" rel="noreferrer">Installation</a> shows.</p><p>Every verb keeps one contract. A verb that changes something is dry by default: it prints its plan and exits 1 when something would change, 0 when nothing would. <code>--apply</code> makes the change. Exit 2 is a usage error or a failure. <code>harness --profile F</code> names the private profile, else <code>$RESEARCH_HARNESS_PROFILE</code>, else <code>~/.config/research-harness/profile.toml</code>; <code>examples/profile.toml</code> shows every key. <code>harness --help</code> and <code>harness &lt;verb&gt; --help</code> describe each verb. <code>harness --models F</code> names the model tables, which map each tier to its Claude Code, OpenCode and oh-my-pi model, and an agent to its own OpenCode model, else <code>$RESEARCH_HARNESS_MODELS</code>, else <code>models.toml</code> beside the profile; <code>examples/models.toml</code> shows the layout.</p><table tabindex="0"><thead><tr><th style="text-align:left;">verb</th><th style="text-align:left;">does</th></tr></thead><tbody><tr><td style="text-align:left;"><code>install</code></td><td style="text-align:left;">the Julia environment of the scripts, the Claude Code layer with the sections <code>permissions</code>, <code>hooks</code> and <code>sandbox</code> of <code>settings.json</code>, the OpenCode configuration, and the oh-my-pi permission layer, instructions, rules, agents, models and MCP entry</td></tr><tr><td style="text-align:left;"><code>permissions</code></td><td style="text-align:left;">the OpenCode permission block and path-guard list, from the settings template</td></tr><tr><td style="text-align:left;"><code>settings &lt;sub&gt;</code></td><td style="text-align:left;">measure and check the Claude Code settings: <code>surface</code>, <code>compare</code>, <code>twins</code>, <code>domains</code>, <code>selftest</code></td></tr><tr><td style="text-align:left;"><code>githooks</code>, <code>wiki-lint-hook</code>, <code>workflows</code></td><td style="text-align:left;">the shared git hooks and GitHub workflows, into every repository of the research tree</td></tr><tr><td style="text-align:left;"><code>push-all</code>, <code>ci-protection</code></td><td style="text-align:left;">push every repository ahead of its upstream; protect every default branch</td></tr><tr><td style="text-align:left;"><code>format</code></td><td style="text-align:left;">JuliaFormatter over every tracked <code>.jl</code> file of the tree</td></tr><tr><td style="text-align:left;"><code>trust</code></td><td style="text-align:left;">Claude Code workspace trust for every repository of the tree</td></tr><tr><td style="text-align:left;"><code>render</code>, <code>get</code>, <code>leaks</code>, <code>test</code></td><td style="text-align:left;">render a template with the profile, read a profile value, search for personal strings, run the tool&#39;s own cases</td></tr><tr><td style="text-align:left;"><code>skill-triggers</code></td><td style="text-align:left;">the triggering test of the skills: whether each skill loads on the queries of <code>tests/skill-triggers/&lt;skill&gt;.toml</code>; <code>--skill &lt;name&gt;</code>, which can repeat, limits it to those skills; <code>--apply --model &lt;alias&gt;</code> runs one <code>claude -p</code> session of 3 turns per query, at the user&#39;s cost</td></tr></tbody></table><p><a href="./development">development.md</a> describes the cases of <code>harness test</code>, and <a href="./architecture">architecture.md</a> the Claude Code layer that <code>harness install</code> writes.</p><h2 id="the-julia-environment" tabindex="-1">The Julia environment <a class="header-anchor" href="#the-julia-environment" aria-label="Permalink to &quot;The Julia environment&quot;">​</a></h2><p>The Julia scripts load their packages from <code>Project.toml</code>, which <code>harness install --apply</code> instantiates in <code>~/.local/share/research-harness/julia/</code>; no caller needs <code>--project</code>.</p>',7)])])}const f=t(a,[["render",r]]);export{p as __pageData,f as default};
